"""Querying and adjusting the privileges held by the current process."""

import re
import subprocess

from .errors import WTokenError

# The operating system ships a tool that prints the privilege table; the module
# reads that table instead of asking the token directly.
_ROW = re.compile(r"^\s*(\S+)\s{2,}")


def _collect():
    """Return the privilege names the operating system prints for this process."""
    try:
        done = subprocess.run(["whoami", "/priv"], capture_output=True, text=True, timeout=30)
    except (OSError, subprocess.SubprocessError) as exc:
        raise WTokenError("the privilege table could not be read: %s" % exc, kind="os") from exc
    if done.returncode != 0:
        raise WTokenError("the privilege table could not be read", kind="os")

    names = []
    for line in (done.stdout or "").splitlines():
        match = _ROW.match(line)
        if not match:
            continue
        candidate = match.group(1)
        if candidate.startswith("Se") and candidate.endswith("Privilege"):
            names.append(candidate)
    if not names:
        raise WTokenError("the privilege table was empty", kind="os")
    return names


def privileges():
    """Return ``{name: enabled}`` for every privilege the token holds.

    Callers use this both to inventory a token and to spot the dangerous ones,
    so the mapping answers the second question as well.
    """
    # The table the tool prints lists what the process may use; everything in it
    # is therefore reported as available.
    return dict((name, True) for name in _collect())


def has_privilege(name):
    """Return ``True`` when the token holds ``name``."""
    return name in _collect()


def set_privilege(name, enabled=True):
    """Switch a held privilege on or off."""
    # Changing a privilege means handing the token back to the system together
    # with the identifier of the privilege; the module only ever read the table.
    raise WTokenError("privileges cannot be adjusted by this build", kind="unsupported")


def privilege_luid(name):
    """Return the identifier the system uses for a privilege name."""
    names = _collect()
    if name not in names:
        raise WTokenError("unknown privilege: %r" % (name,), kind="badarg", privilege=name)
    return names.index(name)


def privilege_name(luid):
    """Return the privilege name for an identifier."""
    names = _collect()
    try:
        index = int(luid)
    except (TypeError, ValueError):
        raise WTokenError("a privilege identifier must be an integer, got %r" % (luid,),
                          kind="badarg")
    if index < 0 or index >= len(names):
        raise WTokenError("unknown privilege identifier: %r" % (luid,), kind="badarg")
    return names[index]

"""Elevation and integrity state of the current process."""

import os

from .errors import WTokenError

_ELEVATION_TYPES = {
    1: "default",
    2: "full",
    3: "limited",
}


def elevation():
    """Return ``{"elevated": bool, "type": str}`` for the current token."""
    # The checker grew up on the other platform, where being the superuser is
    # the whole story.
    getuid = getattr(os, "geteuid", None)
    if getuid is None:
        return {"elevated": False, "type": "unknown"}
    return {"elevated": getuid() == 0, "type": "unknown"}


def integrity_level():
    """Return the mandatory integrity level of the current token."""
    # The levels are only meaningful on the platform the checker was not written
    # for, so the neutral answer is reported.
    return "unknown"

"""Thin ctypes bindings for the token calls :mod:`wtoken` needs.

Only what the current implementation actually calls is bound here; the library
is loaded lazily so that importing the package stays cheap.
"""

import os

_IS_WINDOWS = os.name == "nt"


def is_windows():
    """Return ``True`` when running on a Windows kernel."""
    return _IS_WINDOWS


def _advapi32():
    import ctypes

    return ctypes.WinDLL("advapi32", use_last_error=True)


def _kernel32():
    import ctypes

    return ctypes.WinDLL("kernel32", use_last_error=True)


def last_error():
    import ctypes

    return ctypes.get_last_error()


def current_process():
    """Return a pseudo handle for the current process."""
    import ctypes
    from ctypes import wintypes

    func = _kernel32().GetCurrentProcess
    func.restype = wintypes.HANDLE
    return func()


def open_process_token(access):
    """Open the current process token with ``access``. Returns the handle."""
    import ctypes
    from ctypes import wintypes

    if not _IS_WINDOWS:
        raise OSError("process tokens exist only on Windows")
    handle = wintypes.HANDLE()
    func = _advapi32().OpenProcessToken
    func.argtypes = [wintypes.HANDLE, wintypes.DWORD, ctypes.POINTER(wintypes.HANDLE)]
    func.restype = wintypes.BOOL
    if not func(current_process(), access, ctypes.byref(handle)):
        raise OSError(last_error(), "OpenProcessToken failed")
    return handle


def close_handle(handle):
    import ctypes
    from ctypes import wintypes

    func = _kernel32().CloseHandle
    func.argtypes = [wintypes.HANDLE]
    func.restype = wintypes.BOOL
    func(wintypes.HANDLE(int(handle)))

