from .errors import WTokenError
from ._winapi import is_windows


def _ensure_windows():
    """Raise WTokenError if not on Windows."""
    if not is_windows():
        raise WTokenError(
            "token operations require Windows",
            kind="unsupported",
        )


def elevation():
    """Return ``{"elevated": bool, "type": str}`` for the current token.

    ``elevated`` is ``True`` when the token carries an elevated (administrative)
    set of privileges.  ``type`` is one of ``"default"``, ``"full"``, or
    ``"limited"``, matching the ``TOKEN_ELEVATION_TYPE`` enumeration.
    """
    _ensure_windows()
    from ._winapi import (
        open_process_token, get_token_elevation, close_handle, TOKEN_QUERY,
    )

    handle = None
    try:
        handle = open_process_token(TOKEN_QUERY)
        is_elevated, etype = get_token_elevation(handle)
        return {"elevated": is_elevated, "type": etype}
    except OSError as exc:
        raise WTokenError(
            "failed to query token elevation: %s" % exc,
            kind="os",
        ) from exc
    finally:
        if handle is not None:
            close_handle(handle)


def integrity_level():
    """Return the mandatory integrity level name of the current token.

    Typical values are ``"untrusted"``, ``"low"``, ``"medium"``, ``"high"``,
    ``"system"``, and ``"protected-process"``.
    """
    _ensure_windows()
    from ._winapi import (
        open_process_token, get_token_integrity_level, close_handle, TOKEN_QUERY,
    )

    handle = None
    try:
        handle = open_process_token(TOKEN_QUERY)
        return get_token_integrity_level(handle)
    except OSError as exc:
        raise WTokenError(
            "failed to query token integrity level: %s" % exc,
            kind="os",
        ) from exc
    finally:
        if handle is not None:
            close_handle(handle)

